require_once __DIR__.'/../includes/functions.php';wajibRole('guru');$pageTitle='Pemantauan Klaim';$rows=$koneksi->query('SELECT k.*,l.nama_barang,u.nama FROM klaim k JOIN laporan l ON l.id_laporan=k.id_laporan JOIN users u ON u.id_user=k.id_user ORDER BY k.created_at DESC');require __DIR__.'/../includes/header.php';?><div class="panel"><h2>Pemantauan klaim barang</h2><p class="muted" style="font-size:11px">Guru dapat memantau status klaim. Persetujuan akhir dilakukan admin.</p><div class="table-wrap"><table><tr><th>Barang</th><th>Pemohon</th><th>Bukti</th><th>Status</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=e($r['nama_barang'])?></td><td><?=e($r['nama'])?></td><td><?=e($r['bukti_kepemilikan'])?></td><td><span class="badge <?=e($r['status_klaim'])?>"><?=e($r['status_klaim'])?></span></td></tr><?php endwhile;?></table></div></div><?php require __DIR__.'/../includes/footer.php';?>
